import { Component, type ErrorInfo, type ReactNode, useState } from 'react';
import './styles/global.css';

type View = 'library' | 'read-later';

interface ErrorBoundaryState {
  failed: boolean;
}

class ErrorBoundary extends Component<{ children: ReactNode }, ErrorBoundaryState> {
  state: ErrorBoundaryState = { failed: false };

  static getDerivedStateFromError(): ErrorBoundaryState {
    return { failed: true };
  }

  componentDidCatch(error: Error, details: ErrorInfo): void {
    console.error('The application view failed', error, details.componentStack);
  }

  render(): ReactNode {
    if (this.state.failed) {
      return (
        <main className="shell shell--message">
          <h1>Bookmarks</h1>
          <p role="alert">The library could not be displayed. Reload the page to try again.</p>
        </main>
      );
    }
    return this.props.children;
  }
}

function ApplicationShell() {
  const [view, setView] = useState<View>('library');

  return (
    <div className="app" data-harness-ready="true">
      <header className="masthead">
        <a className="brand" href="/" onClick={(event) => { event.preventDefault(); setView('library'); }}>
          Keepsake
        </a>
        <nav aria-label="Primary navigation">
          <button aria-current={view === 'library' ? 'page' : undefined} onClick={() => setView('library')}>
            Library
          </button>
          <button aria-current={view === 'read-later' ? 'page' : undefined} onClick={() => setView('read-later')}>
            Read later
          </button>
        </nav>
      </header>
      <main className="shell" id="main-content">
        <p className="eyebrow">Personal bookmark manager</p>
        <h1>{view === 'library' ? 'Your library' : 'Read later'}</h1>
        <p className="lede">
          {view === 'library'
            ? 'Save the useful corners of the web and find them again.'
            : 'A quiet queue for the things you want to return to.'}
        </p>
        <section className="empty-state" aria-labelledby="empty-heading">
          <h2 id="empty-heading">{view === 'library' ? 'Your first bookmark starts here' : 'Nothing waiting'}</h2>
          <p>{view === 'library' ? 'Paste a link to begin building your collection.' : 'Unread bookmarks you save for later will appear here.'}</p>
        </section>
      </main>
      <div className="sr-only" aria-live="polite" aria-atomic="true" role="status" id="operation-status" />
    </div>
  );
}

export function App() {
  return <ErrorBoundary><ApplicationShell /></ErrorBoundary>;
}

