export const MAX_SEARCH_QUERY_LENGTH = 1_000;
export const MAX_SEARCH_CLAUSES = 50;

export type TextClause = {
  type: 'text';
  value: string;
  exact: boolean;
};

export type TagAnyClause = {
  type: 'tagAny';
  values: string[];
};

export type SearchClause = TextClause | TagAnyClause;

